<?php
require __DIR__.'/includes/bootstrap.php';require_permission('tasks.view');$pdo=db();
$status=trim((string)($_GET['status']??''));$where='1=1';$params=[];if($status!==''){$where='t.status=?';$params[]=$status;}
$q=$pdo->prepare("SELECT t.*,e.full_name assignee,c.name category FROM tasks t LEFT JOIN employees e ON e.id=t.primary_assignee_id LEFT JOIN task_categories c ON c.id=t.category_id WHERE $where ORDER BY FIELD(t.priority,'urgent','high','medium','low'),COALESCE(t.due_at,'2999-12-31')");$q->execute($params);$tasks=$q->fetchAll();
$employees=$pdo->query("SELECT id,user_id,full_name FROM employees WHERE employment_status='active' ORDER BY full_name")->fetchAll();$categories=$pdo->query('SELECT * FROM task_categories WHERE is_active=1 ORDER BY name')->fetchAll();
$title='Task Management';$active='tasks';include __DIR__.'/includes/header.php';
?>
<section class="section-toolbar reveal"><div><p class="eyebrow">Execution workspace</p><h2>Task management</h2><p class="muted">Full CRUD task board with employee assignment, deadlines, priority, workflow status, and progress.</p></div><?php if(can('tasks.create')):?><button class="btn btn-primary" data-modal-open="taskModal" id="new-task"><i data-lucide="plus"></i>Create task</button><?php endif;?></section>
<section class="task-board reveal stagger-1"><?php foreach(['backlog'=>'Backlog','to_do'=>'To Do','in_progress'=>'In Progress','blocked'=>'Blocked','in_review'=>'In Review','completed'=>'Completed'] as $key=>$label):$list=array_values(array_filter($tasks,fn($t)=>$t['status']===$key));?><div class="task-column"><div class="column-head"><span><?=$label?></span><b><?=count($list)?></b></div><div class="task-stack"><?php if(!$list):?><div class="column-empty">No tasks</div><?php else:foreach($list as $t):$editPayload=['id'=>(int)$t['id'],'title'=>$t['title'],'description'=>$t['description']??'','primary_assignee_id'=>(int)$t['primary_assignee_id'],'category_id'=>(int)$t['category_id'],'priority'=>$t['priority'],'due_at'=>$t['due_at']?date('Y-m-d\TH:i',strtotime($t['due_at'])):'','status'=>$t['status'],'progress'=>(int)$t['progress']];?><article class="task-card"><div class="task-tags"><span class="priority <?=e($t['priority'])?>"><?=e(ucfirst($t['priority']))?></span><small><?=e($t['task_code'])?></small></div><h4><?=e($t['title'])?></h4><p><?=e(mb_strimwidth($t['description']??'No description',0,100,'…'))?></p><div class="task-assignee"><span class="avatar tiny"><?=e(strtoupper(substr($t['assignee']??'U',0,1)))?></span><span><?=e($t['assignee']??'Unassigned')?></span></div><div class="progress-mini"><span style="width:<?=e((string)$t['progress'])?>%"></span></div><div class="task-bottom"><span class="<?=($t['due_at']&&strtotime($t['due_at'])<time()&&!in_array($t['status'],['completed','cancelled'],true))?'danger-text':''?>"><i data-lucide="clock-3"></i><?=e($t['due_at']?format_datetime($t['due_at'],'d M, h:i A'):'No deadline')?></span><?php if(can('tasks.edit')):?><div class="toolbar-actions"><button class="icon-btn sm" title="Edit task" data-task-edit='<?=e(json_encode($editPayload,JSON_UNESCAPED_SLASHES))?>'><i data-lucide="pencil"></i></button><form method="post" action="<?=e(url('handlers/task-delete.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$t['id']?>"><button class="icon-btn sm danger-text" title="Delete task" data-confirm="Delete task <?=e($t['task_code'])?>?"><i data-lucide="trash-2"></i></button></form></div><?php endif;?></div></article><?php endforeach;endif;?></div></div><?php endforeach;?></section>
<div class="modal" id="taskModal" aria-hidden="true"><div class="modal-card"><button class="modal-close" data-modal-close><i data-lucide="x"></i></button><p class="eyebrow">New responsibility</p><h3>Create task</h3><form class="form-grid" method="post" action="<?=e(url('handlers/task-save.php'))?>"><?=csrf_field()?><label class="span-2">Task title<input name="title" required></label><label class="span-2">Description<textarea name="description" rows="4"></textarea></label><label>Assignee<select name="primary_assignee_id" required><option value="">Select employee</option><?php foreach($employees as $emp):?><option value="<?=$emp['id']?>"><?=e($emp['full_name'])?></option><?php endforeach;?></select></label><label>Category<select name="category_id"><option value="">No category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><option value="medium">Medium</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></label><label>Due date & time<input type="datetime-local" name="due_at"></label><div class="form-actions span-2"><button type="button" class="btn btn-soft" data-modal-close>Cancel</button><button class="btn btn-primary">Assign task</button></div></form></div></div>
<div class="modal" id="taskEditModal" aria-hidden="true"><div class="modal-card"><button class="modal-close" data-modal-close><i data-lucide="x"></i></button><p class="eyebrow">Task CRUD</p><h3 id="taskEditTitle">Edit task</h3><form method="post" id="taskEditForm" action="<?=e(url('handlers/task-update.php'))?>" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" id="taskEditId"><label class="span-2">Task title<input name="title" id="taskEditName" required></label><label class="span-2">Description<textarea name="description" id="taskEditDescription" rows="4"></textarea></label><label>Assignee<select name="primary_assignee_id" id="taskEditAssignee" required><?php foreach($employees as $emp):?><option value="<?=$emp['id']?>"><?=e($emp['full_name'])?></option><?php endforeach;?></select></label><label>Category<select name="category_id" id="taskEditCategory"><option value="">No category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Priority<select name="priority" id="taskEditPriority"><?php foreach(['low','medium','high','urgent'] as $p):?><option value="<?=$p?>"><?=e(ucfirst($p))?></option><?php endforeach;?></select></label><label>Due date & time<input type="datetime-local" name="due_at" id="taskEditDue"></label><label>Status<select name="status" id="taskEditStatus"><?php foreach(['backlog','to_do','in_progress','blocked','in_review','completed','cancelled'] as $s):?><option value="<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></label><label>Progress <span id="progressValue">0%</span><input type="range" name="progress" id="taskProgress" min="0" max="100" step="5"></label><div class="form-actions span-2"><button type="button" class="btn btn-soft" data-modal-close>Cancel</button><button class="btn btn-primary">Save task changes</button></div></form></div></div>
<?php include __DIR__.'/includes/footer.php';?>
